mkitem!{mkstruct!{pub struct ObligationForest < O : ForestObligation > { # [doc = " The list of obligations. In between calls to [Self::process_obligations],"] # [doc = " this list only contains nodes in the `Pending` or `Waiting` state."] # [doc = ""] # [doc = " `usize` indices are used here and throughout this module, rather than"] # [doc = " [`rustc_index::newtype_index!`] indices, because this code is hot enough"] # [doc = " that the `u32`-to-`usize` conversions that would be required are"] # [doc = " significant, and space considerations are not important."] nodes : Vec < Node < O > > , # [doc = " A cache of predicates that have been successfully completed."] done_cache : FxHashSet < O :: CacheKey > , # [doc = " A cache of the nodes in `nodes`, indexed by predicate. Unfortunately,"] # [doc = " its contents are not guaranteed to match those of `nodes`. See the"] # [doc = " comments in `Self::process_obligation` for details."] active_cache : FxHashMap < O :: CacheKey , usize > , # [doc = " A vector reused in [Self::compress()] and [Self::find_cycles_from_node()],"] # [doc = " to avoid allocating new vectors."] reused_node_vec : Vec < usize > , obligation_tree_id_generator : ObligationTreeIdGenerator , # [doc = " Per tree error cache. This is used to deduplicate errors,"] # [doc = " which is necessary to avoid trait resolution overflow in"] # [doc = " some cases."] # [doc = ""] # [doc = " See [this][details] for details."] # [doc = ""] # [doc = " [details]: https://github.com/rust-lang/rust/pull/53255#issuecomment-421184780"] error_cache : FxHashMap < ObligationTreeId , FxHashSet < O :: CacheKey > > , }}}
mkitem!{mkstruct!{# [derive (Debug)] struct Node < O > { obligation : O , state : Cell < NodeState > , # [doc = " Obligations that depend on this obligation for their completion. They"] # [doc = " must all be in a non-pending state."] dependents : Vec < usize > , # [doc = " If true, `dependents[0]` points to a \"parent\" node, which requires"] # [doc = " special treatment upon error but is otherwise treated the same."] # [doc = " (It would be more idiomatic to store the parent node in a separate"] # [doc = " `Option<usize>` field, but that slows down the common case of"] # [doc = " iterating over the parent and other descendants together.)"] has_parent : bool , # [doc = " Identifier of the obligation tree to which this node belongs."] obligation_tree_id : ObligationTreeId , }}}
mkitem!{mkimpl!{impl < O > Node < O > { fn new (parent : Option < usize > , obligation : O , obligation_tree_id : ObligationTreeId) -> Node < O > { Node { obligation , state : Cell :: new (NodeState :: Pending) , dependents : if let Some (parent_index) = parent { vec ! [parent_index] } else { vec ! [] } , has_parent : parent . is_some () , obligation_tree_id , } } }}}
mkitem!{mkenum!{# [doc = " The state of one node in some tree within the forest. This represents the"] # [doc = " current state of processing for the obligation (of type `O`) associated"] # [doc = " with this node."] # [doc = ""] # [doc = " The non-`Error` state transitions are as follows."] # [doc = " ```text"] # [doc = " (Pre-creation)"] # [doc = "  |"] # [doc = "  |     register_obligation_at() (called by process_obligations() and"] # [doc = "  v                               from outside the crate)"] # [doc = " Pending"] # [doc = "  |"] # [doc = "  |     process_obligations()"] # [doc = "  v"] # [doc = " Success"] # [doc = "  |  ^"] # [doc = "  |  |  mark_successes()"] # [doc = "  |  v"] # [doc = "  |  Waiting"] # [doc = "  |"] # [doc = "  |     process_cycles()"] # [doc = "  v"] # [doc = " Done"] # [doc = "  |"] # [doc = "  |     compress()"] # [doc = "  v"] # [doc = " (Removed)"] # [doc = " ```"] # [doc = " The `Error` state can be introduced in several places, via `error_at()`."] # [doc = ""] # [doc = " Outside of `ObligationForest` methods, nodes should be either `Pending` or"] # [doc = " `Waiting`."] # [derive (Debug , Copy , Clone , PartialEq , Eq)] enum NodeState { # [doc = " This obligation has not yet been selected successfully. Cannot have"] # [doc = " subobligations."] Pending , # [doc = " This obligation was selected successfully, but may or may not have"] # [doc = " subobligations."] Success , # [doc = " This obligation was selected successfully, but it has a pending"] # [doc = " subobligation."] Waiting , # [doc = " This obligation, along with its subobligations, are complete, and will"] # [doc = " be removed in the next collection."] Done , # [doc = " This obligation was resolved to an error. It will be removed by the"] # [doc = " next compression step."] Error , }}}
mkitem!{mktrait!{# [doc = " This trait allows us to have two different Outcome types:"] # [doc = "  - the normal one that does as little as possible"] # [doc = "  - one for tests that does some additional work and checking"] pub trait OutcomeTrait { type Error ; type Obligation ; fn new () -> Self ; fn record_completed (& mut self , outcome : & Self :: Obligation) ; fn record_error (& mut self , error : Self :: Error) ; }}}
mkitem!{mkstruct!{# [derive (Debug)] pub struct Outcome < O , E > { # [doc = " Backtrace of obligations that were found to be in error."] pub errors : Vec < Error < O , E > > , }}}
